# aplicar-v71-financeiro-graficos-ir.ps1
# Melhora a tela /admin/orders para ADMIN e SUPER_ADMIN.
#
# O que muda:
# - Dashboard financeiro completo
# - Graficos SVG bonitos sem depender de biblioteca externa
# - Receita diaria, status, métodos de pagamento e ranking de eventos
# - Filtros por período, data inicial/final, evento, status e busca
# - Exportação CSV de pedidos
# - Exportação CSV de relatório para contador/IR
# - Cards de receita bruta, líquida operacional, estornos, ticket médio, documentos únicos
#
# Observação: é relatório operacional para conferência/contador, não substitui escrituração fiscal oficial.

$ErrorActionPreference = "Stop"

$Root = Get-Location
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"

function Write-TextBase64File($RelativePath, $Base64Content) {
  $Target = Join-Path $Root $RelativePath
  $TargetDir = Split-Path $Target -Parent

  if (-not (Test-Path $TargetDir)) {
    New-Item -ItemType Directory -Path $TargetDir -Force | Out-Null
  }

  if (Test-Path $Target) {
    $Backup = "$Target.bak-v71-$Stamp"
    Copy-Item $Target $Backup -Force
    Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray
  }

  $Content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64Content))
  Set-Content -Path $Target -Value $Content -Encoding UTF8
  Write-Host "Atualizado: $RelativePath" -ForegroundColor Green
}

Write-Host "Aplicando v71 - financeiro com graficos e relatorio IR..." -ForegroundColor Cyan

$OrdersPageBase64 = ""

Write-TextBase64File "apps\web\src\app\admin\orders\page.tsx" $OrdersPageBase64

Write-Host ""
Write-Host "v71 aplicada com sucesso." -ForegroundColor Green
Write-Host ""
Write-Host "Agora a tela /admin/orders tem:" -ForegroundColor Cyan
Write-Host "- Graficos financeiros parrudos" -ForegroundColor Cyan
Write-Host "- Filtros por periodo e datas" -ForegroundColor Cyan
Write-Host "- Exportacao de pedidos CSV" -ForegroundColor Cyan
Write-Host "- Exportacao de relatorio para contador/IR" -ForegroundColor Cyan
Write-Host ""
Write-Host "Reinicie o WEB:" -ForegroundColor Cyan
Write-Host 'cd "C:\Users\march\OneDrive\Área de Trabalho\plataforma-ingressos\apps\web"' -ForegroundColor Cyan
Write-Host "npm run dev" -ForegroundColor Cyan
